function [ok,evidence]=sat_d014_is_trusted_continuous_average_vsc(blockOrFacts)
%SAT_D014_IS_TRUSTED_CONTINUOUS_AVERAGE_VSC Exact SPS average-VSC identity.
% Device="Average-model based VSC" on the linked three-arm SPS Universal
% Bridge is the official continuous average model 3 representation.

if isstruct(blockOrFacts)
    f=blockOrFacts;
else
    block=char(string(blockOrFacts));
    f=struct( ...
        'path',string(block), ...
        'block_type',getp(block,'BlockType'), ...
        'mask_type',getp(block,'MaskType'), ...
        'reference_block',getp(block,'ReferenceBlock'), ...
        'library_source_block',getp(block,'LibrarySourceBlock'), ...
        'link_status',getp(block,'LinkStatus'), ...
        'device',getp(block,'Device'), ...
        'arms',getp(block,'Arms'), ...
        'converter_type',getp(block,'converterType'));
    ports=struct();try,ports=get_param(block,'PortHandles');catch,end
    f.inport_count=port_count(ports,'Inport');
    f.lconn_count=port_count(ports,'LConn');
    f.rconn_count=port_count(ports,'RConn');
end

path=text(f,'path');
blockType=normtext(text(f,'block_type'));
maskType=normtext(text(f,'mask_type'));
referenceBlock=normtext(text(f,'reference_block'));
librarySource=normtext(text(f,'library_source_block'));
linkStatus=normtext(text(f,'link_status'));
device=normtext(text(f,'device'));
arms=number(f,'arms');
converterType=normtext(text(f,'converter_type'));
inports=number(f,'inport_count');
lconns=number(f,'lconn_count');
rconns=number(f,'rconn_count');

checks=struct( ...
    'official_reference',referenceBlock=="spsuniversalbridgelib/universal bridge", ...
    'official_library_source',librarySource=="sps_lib/power electronics/universal bridge", ...
    'resolved_link',linkStatus=="resolved", ...
    'universal_bridge_mask',blockType=="subsystem"&&maskType=="universal bridge", ...
    'continuous_average_model_3',device=="average-model based vsc", ...
    'three_arm_inverter',arms==3&&converterType=="inverter", ...
    'expected_ports',inports==1&&lconns==3&&rconns==2);
ok=all(structfun(@logical,checks));
evidence=struct( ...
    'path',path, ...
    'reference_block',referenceBlock, ...
    'library_source_block',librarySource, ...
    'link_status',linkStatus, ...
    'device',device, ...
    'canonical_mode',"continuous average model 3", ...
    'arms',arms, ...
    'converter_type',converterType, ...
    'inport_count',inports, ...
    'lconn_count',lconns, ...
    'rconn_count',rconns, ...
    'checks',checks);
end

function value=getp(block,param)
value='';try,value=get_param(block,param);catch,end
end
function n=port_count(ports,name)
n=0;if isstruct(ports)&&isfield(ports,name),n=numel(ports.(name));end
end
function value=text(s,name)
value="";if isstruct(s)&&isfield(s,name),value=string(s.(name));end
if ~isscalar(value),value="";end
end
function value=number(s,name)
value=NaN;if ~isstruct(s)||~isfield(s,name),return;end
raw=s.(name);if isnumeric(raw)&&isscalar(raw),value=double(raw);return;end
value=str2double(string(raw));if ~isscalar(value),value=NaN;end
end
function value=normtext(value)
value=lower(regexprep(strtrim(string(value)),'\s+',' '));
value=replace(value,'\','/');
end
